"use client";

import { useSyncExternalStore, type ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./kbd.css";

export type KbdPlatform = "mac" | "other";

/* Each key: the glyph people see on that platform, and the word a screen reader says. */
const named: Record<string, { mac: string; other: string; spoken: string; aria: string }> = {
  mod: { mac: "⌘", other: "Ctrl", spoken: "Command", aria: "Meta" },
  cmd: { mac: "⌘", other: "⌘", spoken: "Command", aria: "Meta" },
  meta: { mac: "⌘", other: "Win", spoken: "Command", aria: "Meta" },
  ctrl: { mac: "⌃", other: "Ctrl", spoken: "Control", aria: "Control" },
  alt: { mac: "⌥", other: "Alt", spoken: "Option", aria: "Alt" },
  option: { mac: "⌥", other: "Alt", spoken: "Option", aria: "Alt" },
  shift: { mac: "⇧", other: "Shift", spoken: "Shift", aria: "Shift" },
  enter: { mac: "↵", other: "Enter", spoken: "Enter", aria: "Enter" },
  return: { mac: "↵", other: "Enter", spoken: "Return", aria: "Enter" },
  esc: { mac: "Esc", other: "Esc", spoken: "Escape", aria: "Escape" },
  escape: { mac: "Esc", other: "Esc", spoken: "Escape", aria: "Escape" },
  tab: { mac: "⇥", other: "Tab", spoken: "Tab", aria: "Tab" },
  backspace: { mac: "⌫", other: "Backspace", spoken: "Backspace", aria: "Backspace" },
  delete: { mac: "⌦", other: "Del", spoken: "Delete", aria: "Delete" },
  space: { mac: "Space", other: "Space", spoken: "Space", aria: "Space" },
  up: { mac: "↑", other: "↑", spoken: "Up arrow", aria: "ArrowUp" },
  down: { mac: "↓", other: "↓", spoken: "Down arrow", aria: "ArrowDown" },
  left: { mac: "←", other: "←", spoken: "Left arrow", aria: "ArrowLeft" },
  right: { mac: "→", other: "→", spoken: "Right arrow", aria: "ArrowRight" },
  pageup: { mac: "PgUp", other: "PgUp", spoken: "Page up", aria: "PageUp" },
  pagedown: { mac: "PgDn", other: "PgDn", spoken: "Page down", aria: "PageDown" },
  home: { mac: "Home", other: "Home", spoken: "Home", aria: "Home" },
  end: { mac: "End", other: "End", spoken: "End", aria: "End" },
};

/** "mod+shift+k" or ["mod", "K"] → ["mod", "shift", "k"]. A lone "+" stays a key. */
function tokens(keys: string | readonly string[]) {
  if (typeof keys !== "string") return [...keys];
  if (keys === "+") return ["+"];
  return keys.split(/\+(?!$)/u).map((key) => key.trim()).filter(Boolean);
}

function describe(key: string, platform: KbdPlatform) {
  const known = named[key.toLowerCase()];
  if (known) return { glyph: known[platform], spoken: known.spoken, aria: known.aria };
  const glyph = key.length === 1 ? key.toUpperCase() : key;
  return { glyph, spoken: glyph, aria: glyph };
}

function detect(): KbdPlatform {
  const nav = navigator as Navigator & { userAgentData?: { platform?: string } };
  const name = nav.userAgentData?.platform ?? nav.platform ?? "";
  return /mac|iphone|ipad|ipod/iu.test(name) ? "mac" : "other";
}

/** The platform's modifier names. The server renders "other"; Macs switch to ⌘ after hydration. */
export function useKbdPlatform(platform?: KbdPlatform): KbdPlatform {
  const detected = useSyncExternalStore(
    () => () => {},
    detect,
    () => "other" as const,
  );
  return platform ?? detected;
}

/** The value for `aria-keyshortcuts` on the control the keys trigger, e.g. "Meta+K". */
export function toAriaKeyshortcuts(keys: string | readonly string[], platform: KbdPlatform = "other") {
  return tokens(keys)
    .map((key) => {
      if (key.toLowerCase() === "mod") return platform === "mac" ? "Meta" : "Control";
      return describe(key, platform).aria;
    })
    .join("+");
}

export type KbdProps = Omit<ComponentProps<"kbd">, "children"> & {
  /** One key or a combination: "mod+k", "shift+enter", ["alt", "↑"]. `mod` is ⌘ on a Mac and Ctrl elsewhere. */
  keys?: string | readonly string[];
  /** Free text instead of keys, e.g. "G then D". */
  children?: string;
  /** `inline` sits quietly inside a button, menu row or tooltip and takes its colour. */
  variant?: "default" | "inline";
  size?: "sm" | "md";
  /** Force a platform instead of detecting it, e.g. in documentation. */
  platform?: KbdPlatform;
};

/**
 * Keys drawn as small raised caps. A combination is one `kbd` holding a cap
 * per key, so it reads as a single shortcut; symbols such as ⌘ carry their
 * spoken name for screen readers.
 */
export function Kbd({ keys, children, variant = "default", size = "md", platform, className, ...props }: KbdProps) {
  const resolved = useKbdPlatform(platform);
  const list = keys !== undefined ? tokens(keys) : children !== undefined ? [children] : [];
  const parts = list.map((key) => describe(key, resolved));
  const shared = { "data-variant": variant, "data-size": size } as const;
  if (parts.length === 1) {
    return (
      <kbd data-slot="kbd" {...shared} className={className} {...props}>
        <Glyph {...parts[0]!} />
      </kbd>
    );
  }
  return (
    <kbd data-slot="kbd-group" {...shared} className={cn(className)} {...props}>
      {parts.map((part, index) => (
        <kbd key={index} data-slot="kbd" {...shared}>
          {index > 0 && <span className="sr-only"> </span>}
          <Glyph {...part} />
        </kbd>
      ))}
    </kbd>
  );
}

function Glyph({ glyph, spoken }: { glyph: string; spoken: string }) {
  if (glyph === spoken) return glyph;
  return (
    <>
      <span aria-hidden="true">{glyph}</span>
      <span className="sr-only">{spoken}</span>
    </>
  );
}

"use client";
import { useEffect, useRef, useState, type ComponentProps } from "react";
import { Kbd } from "./kbd";
import { cn } from "./lib/cn";
import "./key-echo.css";

export type KeyEchoProps = Omit<ComponentProps<"div">, "children"> & {
  /** Echo keys pressed anywhere on the page, or only inside the parent element. */
  scope?: "page" | "parent";
  /** How many combinations stay on screen at once. */
  max?: number;
  /** How long a combination stays, in ms. */
  linger?: number;
};

type Echo = { id: number; keys: string[]; times: number };
const names: Record<string, string> = { " ": "Space", ArrowUp: "↑", ArrowDown: "↓", ArrowLeft: "←", ArrowRight: "→", Escape: "Esc", Backspace: "⌫", Enter: "↵" };
const modifiers = ["Control", "Meta", "Alt", "Shift"];

/** The caps for one key event: modifiers first, then the key, for example ["mod", "shift", "K"]. */
export function comboOf(event: Pick<KeyboardEvent, "key" | "metaKey" | "ctrlKey" | "altKey" | "shiftKey">) {
  if (modifiers.includes(event.key)) return null;
  const keys: string[] = [];
  if (event.metaKey) keys.push("meta");
  if (event.ctrlKey) keys.push("ctrl");
  if (event.altKey) keys.push("alt");
  // Shift is shown only with another modifier or a non-character key, as "A" already says shift.
  if (event.shiftKey && (keys.length || event.key.length > 1)) keys.push("shift");
  keys.push(names[event.key] ?? (event.key.length === 1 ? event.key.toUpperCase() : event.key));
  return keys;
}

/**
 * Shows the keys you press as caps that pop up, stack and fade, for screen recordings, tutorials and live demos.
 * Pressing the same combination again counts it instead of adding another. It is a visual echo only, hidden from
 * assistive technology, and ignores keys typed into password fields. Under reduced motion caps appear and leave
 * without travel.
 */
export function KeyEcho({ scope = "page", max = 3, linger = 1600, className, ...props }: KeyEchoProps) {
  const [echoes, setEchoes] = useState<Echo[]>([]);
  const root = useRef<HTMLDivElement>(null);
  const next = useRef(0);

  useEffect(() => {
    const target = scope === "page" ? document : root.current?.parentElement;
    if (!target) return;
    const down = (event: Event) => {
      const key = event as KeyboardEvent;
      if ((key.target as HTMLInputElement | null)?.type === "password") return;
      const keys = comboOf(key);
      if (!keys) return;
      setEchoes((current) => {
        const last = current[current.length - 1];
        if (last && last.keys.join("+") === keys.join("+")) return [...current.slice(0, -1), { ...last, id: next.current++, times: last.times + 1 }];
        return [...current, { id: next.current++, keys, times: 1 }].slice(-max);
      });
    };
    target.addEventListener("keydown", down);
    return () => target.removeEventListener("keydown", down);
  }, [scope, max]);

  // Each combination leaves on its own clock; a repeat restarts it.
  useEffect(() => {
    if (!echoes.length) return;
    const oldest = echoes[0];
    const timer = window.setTimeout(() => setEchoes((current) => current.filter((echo) => echo.id !== oldest.id)), linger);
    return () => window.clearTimeout(timer);
  }, [echoes, linger]);

  return (
    <div ref={root} data-slot="key-echo" aria-hidden="true" className={cn("pointer-events-none flex flex-col items-center gap-2", className)} {...props}>
      {echoes.map((echo) => (
        <span key={echo.id} data-slot="ke-combo" data-repeat={echo.times > 1 ? "" : undefined}>
          <Kbd keys={echo.keys} size="md" />
          {echo.times > 1 && <span data-slot="ke-times">×{echo.times}</span>}
        </span>
      ))}
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* kbd.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Key caps: a small raised object with a lip on the bottom edge. */
  [data-slot="kbd-group"] { display: inline-flex; align-items: center; gap: 3px; font: inherit; }
  [data-slot="kbd"] {
    display: inline-flex; align-items: center; justify-content: center;
    min-width: 20px; height: 20px; padding: 0 5px;
    border-radius: var(--radius-mark);
    background: var(--raised);
    box-shadow: inset 0 0 0 1px var(--border), inset 0 -1px 0 var(--border-strong);
    color: var(--muted-foreground);
    font-family: var(--font-mono, ui-monospace, monospace); font-size: 12px; line-height: 1; font-weight: 500;
    font-variant-numeric: tabular-nums; white-space: nowrap;
  }
  /* A key hint inside a search box or field is a soft fill: the box already has the border. */
  :is([data-slot="input-group"], [data-slot="search"], [data-slot$="-search"], [data-slot="command-input"]) [data-slot="kbd"] { background: var(--muted); box-shadow: none; border: 0; }
  [data-slot="kbd"][data-size="sm"] { min-width: 18px; height: 18px; padding: 0 4px; font-size: 12px; }
  [data-slot="kbd"][data-variant="inline"] {
    background: transparent; color: inherit; opacity: 0.72;
    box-shadow: inset 0 0 0 1px color-mix(in srgb, currentColor 26%, transparent);
  }
  [data-slot="kbd-group"][data-variant="inline"] { opacity: 1; }
}

/* key-echo.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Key echo: caps rise in, a repeat bumps its count, and old combinations fade up and out. */
  [data-slot="key-echo"] [data-slot="ke-combo"] { display: inline-flex; align-items: center; gap: 6px; padding: 6px 8px; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--background); box-shadow: var(--shadow-resting); animation: ke-in 0.28s var(--ease-settle); }
  [data-slot="key-echo"] [data-slot="ke-times"] { font-size: 12px; font-variant-numeric: tabular-nums; color: var(--muted-foreground); animation: ke-bump 0.25s var(--ease-settle); }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="key-echo"] :is([data-slot="ke-combo"], [data-slot="ke-times"]) { animation: none; }
  }
  @keyframes ke-in { from { opacity: 0; translate: 0 8px; scale: 0.94; } }
  @keyframes ke-bump { from { scale: 1.3; } }
}
